import{_ as a,o as r,c as o,ai as i}from"./chunks/framework.lvpqbiZd.js";const m=JSON.parse('{"title":"Asumi Premium Hero Redesign","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-08-31-asumi-premium-hero-redesign.md","filePath":"superpowers/specs/2026-08-31-asumi-premium-hero-redesign.md"}'),t={name:"superpowers/specs/2026-08-31-asumi-premium-hero-redesign.md"};function s(n,e,d,l,c,h){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="asumi-premium-hero-redesign" tabindex="-1">Asumi Premium Hero Redesign <a class="header-anchor" href="#asumi-premium-hero-redesign" aria-label="Permalink to “Asumi Premium Hero Redesign”">​</a></h1><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p>Replace the current line-art treatment with a natural, premium cinematic composition focused only on the Asumi brand and sunrise.</p><h2 id="root-cause" tabindex="-1">Root Cause <a class="header-anchor" href="#root-cause" aria-label="Permalink to “Root Cause”">​</a></h2><p>The current wave uses narrow tube paths, so it reads as an ECG/sine graph. The sun uses circular geometry and radial opacity, so it reads as a yellow disc. Large symmetric torus meshes compete with the logo and flatten the scene.</p><h2 id="approved-composition" tabindex="-1">Approved Composition <a class="header-anchor" href="#approved-composition" aria-label="Permalink to “Approved Composition”">​</a></h2><ul><li>Background: <code>#080A0B</code>, restrained vignette, no visible card or dashboard treatment.</li><li>Horizon: a tiny white-gold source near the lower center, wide horizontal bloom, haze, and vertical reflection. No large circular sun.</li><li>Orbits: three hairline ellipses at <code>6%</code> to <code>15%</code> opacity with different sizes, offsets, and depth.</li><li>Light wave: a broad translucent subdivided surface growing from the horizon toward the right, with charcoal body, soft distortion, gold rim light, and no stroke-based silhouette.</li><li>Content: only <code>ASUMI</code>, <code>明日美</code>, <code>A Beautiful Tomorrow</code>, and <code>آینده‌ای روشن</code>, centered with generous breathing room.</li><li>Typography: geometric sans, light weight, and wide tracking for ASUMI; restrained serif only for the English tagline; proper Persian half-space.</li><li>Hierarchy: brand first, Japanese mark second, meaning third, light atmosphere last.</li></ul><h2 id="loader" tabindex="-1">Loader <a class="header-anchor" href="#loader" aria-label="Permalink to “Loader”">​</a></h2><p>Use the supplied React Bits Strands technique through OGL for a short loading veil. Restrict its palette to warm white, copper gold, and graphite; lower waviness and saturation so it reads as a luminous atmospheric halo rather than a rainbow sine graph. Keep an inline black-and-gold fallback in <code>index.html</code> before React mounts.</p><h2 id="motion" tabindex="-1">Motion <a class="header-anchor" href="#motion" aria-label="Permalink to “Motion”">​</a></h2><p>The loader fades before the Hero timeline begins. The Hero sequence is darkness, horizon source, bloom/reflection, orbit draw, wordmark, Japanese mark, English tagline, Persian tagline, fabric growth, particles, then pointer interaction. Reduced-motion users receive the complete static frame without the timeline.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>Remove the temporary <code>What We Build</code> preview and do not add any lower-page sections. Navigation polish and product pages remain future work.</p>',13)])])}const u=a(t,[["render",s]]);export{m as __pageData,u as default};
